```python
_AUTH_CODE_KEY_PREFIX = "cb:auth:code:"  # shared across uvicorn workers

def _issue_auth_code(token: str) -> str:
    code = secrets.token_urlsafe(32)
    from app.core.redis import get_sync_redis, reset_sync_redis
    client = get_sync_redis()
    if client is not None:
        try:
            client.set(f"{_AUTH_CODE_KEY_PREFIX}{code}", token, ex=int(_AUTH_CODE_TTL), nx=True)
            return code
        except Exception:
            reset_sync_redis()
    # Redis unreachable — single-process fallback
    now = time.monotonic()
    for k in [k for k, (_, exp) in _pending_auth_codes.items() if now > exp]:
        del _pending_auth_codes[k]
    _pending_auth_codes[code] = (token, now + _AUTH_CODE_TTL)
    return code
```

and in `exchange_auth_code`, try Redis first with an atomic redeem before falling back:

```python
    from app.core.redis import get_sync_redis, reset_sync_redis
    client = get_sync_redis()
    if client is not None:
        try:
            token = client.getdel(f"{_AUTH_CODE_KEY_PREFIX}{code}")
            if token:
                return {"token": token}
        except Exception:
            reset_sync_redis()
    entry = _pending_auth_codes.pop(code, None)
    if entry is None or time.monotonic() > entry[1]:
        raise HTTPException(400, "Invalid or expired auth code")
    return {"token": entry[0]}
```

