def trusted_client_ip(conn: Any, default: str = "unknown") -> str:
    """The client address, honouring `X-Forwarded-For` only behind a trusted proxy."""
    if request_from_trusted_proxy(conn):
        forwarded = forwarded_client_identity(getattr(conn, "headers", None))
        if forwarded:
